const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Medina, Saudi Arabia geometry
  const medina = ee.Geometry.Point([39.60, 24.47]);
  const roi = medina.buffer(20000); // 20km buffer for urban area analysis

  // June 1984: Landsat 5 TM
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(roi)
    .filterDate('1984-06-01', '1984-06-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1984 = col1984.size().getInfo();
  console.log(`1984 Images found: ${size1984}`);

  if (size1984 === 0) {
    console.log('No Landsat 5 images for June 1984.');
    console.log('C1');
    return;
  }

  // July 2018: Landsat 8 OLI
  let col2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate('2018-07-01', '2018-07-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2018 = col2018.size().getInfo();
  console.log(`2018 Images found: ${size2018}`);

  if (size2018 === 0) {
    console.log('No Landsat 8 images for July 2018.');
    console.log('C1');
    return;
  }

  // Process 1984 image: Calculate NDBI (Normalized Difference Built-up Index)
  // NDBI = (SWIR - NIR) / (SWIR + NIR) for Landsat 5
  const img1984 = col1984.first();
  const ndbi1984 = img1984.normalizedDifference(['SR_B5', 'SR_B4']) // B5=SWIR, B4=NIR
    .rename('NDBI');
  const urbanMask1984 = ndbi1984.gt(0.1); // Urban threshold

  // Count urban pixels in 1984
  const count1984 = urbanMask1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  console.log(`1984 Urban pixels (NDBI>0.1): ${Math.round(count1984 || 0)}`);

  // Process 2018 image: Calculate NDBI for Landsat 8
  // NDBI = (B6 - B5) / (B6 + B5) for Landsat 8
  const img2018 = col2018.first();
  const ndbi2018 = img2018.normalizedDifference(['SR_B6', 'SR_B5']) // B6=SWIR1, B5=NIR
    .rename('NDBI');
  const urbanMask2018 = ndbi2018.gt(0.1);

  // Count urban pixels in 2018
  const count2018 = urbanMask2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  console.log(`2018 Urban pixels (NDBI>0.1): ${Math.round(count2018 || 0)}`);

  // Validation
  if (count1984 === null || count1984 === undefined || count1984 === 0) {
    console.log('No valid pixels in 1984.');
    console.log('C2');
    return;
  }

  if (count2018 === null || count2018 === undefined || count2018 === 0) {
    console.log('No valid pixels in 2018.');
    console.log('C2');
    return;
  }

  // Compare urban expansion
  const expansion = count2018 - count1984;
  console.log(`Urban area change: ${expansion > 0 ? '+' : ''}${Math.round(expansion)} pixels`);

  if (count2018 > count1984 * 1.05) { // Allow 5% threshold for noise
    console.log('A');
  } else if (count2018 <= count1984 * 1.05) {
    console.log('B');
  } else {
    console.log('C3');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
